std::string component_hex(std::span<const std::byte>b){constexpr char d[]="0123456789abcdef";std::string out;for(auto v:b){const auto n=std::to_integer<unsigned>(v);out+=d[n>>4u];out+=d[n&15u];}return out;}
std::uint32_t component_reg(const user_regs_struct&r,const std::string&s){if(s.empty())return 0;if(s=="eax")return r.rax;if(s=="ebx")return r.rbx;if(s=="ecx")return r.rcx;if(s=="edx")return r.rdx;if(s=="esp")return r.rsp;if(s=="ebp")return r.rbp;if(s=="esi")return r.rsi;if(s=="edi")return r.rdi;throw std::runtime_error("Unknown original component address register");}
